            m_resolver.Stop();
            m_resolver = null;
            PeerData peer = (PeerData) comboBox1.SelectedItem;
			uint bits = BitConverter.ToUInt32( (Byte[])rdata, 0);
			System.Net.IPAddress address = new System.Net.IPAddress(bits);
            peer.Address = address;
		}
